I'll implement the BookDetailViewModel in the BookDetailBottomSheet. First, let's create the view model class, then integrate it into the bottom sheet.

Here's how to implement the changes:

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/main/booksheet/BookDetailViewModel.kt
package tungp.android.bazarbooks.screens.main.booksheet

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import tungp.android.bazarbooks.domain.model.Book
import tungp.android.bazarbooks.domain.usecase.GetBookDetailUseCase
import tungp.android.bazarbooks.mvi.MviViewModel
import tungp.android.bazarbooks.mvi.UiIntent
import tungp.android.bazarbooks.mvi.UiState

class BookDetailViewModel(
 private val getBookDetailUseCase: GetBookDetailUseCase
) : MviViewModel<BookDetailViewModel.Intent, BookDetailViewModel.State>() {

 private val _uiState = MutableStateFlow(State())
 override val uiState: StateFlow<State> = _uiState.asStateFlow()

 sealed class Intent : UiIntent {
 data class LoadBookDetail(val bookId: String) : Intent()
 data class AddToCart(val bookId: String, val quantity: Int) : Intent()
 }

 data class State(
 val isLoading: Boolean = false,
 val book: Book? = null,
 val errorMessage: String? = null,
 val addedToCart: Boolean = false
 ) : UiState

 override fun processIntent(intent: Intent) {
 when (intent) {
 is Intent.LoadBookDetail -> loadBookDetail(intent.bookId)
 is Intent.AddToCart -> addToCart(intent.bookId, intent.quantity)
 }
 }

 private fun loadBookDetail(bookId: String) {
 viewModelScope.launch {
 _uiState.value = _uiState.value.copy(isLoading = true)
 try {
 val book = getBookDetailUseCase(bookId)
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 book = book,
 errorMessage = null
 )
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 errorMessage = e.message
 )
 }
 }
 }

 private fun addToCart(bookId: String, quantity: Int) {
 // Implementation would connect to a repository or use case to add the item to cart
 // For now, we'll just update the UI state
 viewModelScope.launch {
 _uiState.value = _uiState.value.copy(addedToCart = true)
 }
 }
}
```

Now, let's update the BookDetailBottomSheet to use the view model:

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/main/booksheet/BookDetailBottomSheet.kt
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun BookDetailBottomSheet(
 bookId: String,
 viewModel: BookDetailViewModel,
 onDismiss: () -> Unit,
 onNavigateToCart: () -> Unit = {},
 sheetState: SheetState = rememberModalBottomSheetState(),
) {
 val coroutineScope = rememberCoroutineScope()
 val uiState by viewModel.uiState.collectAsState()

 // Load book details when the sheet is shown
 LaunchedEffect(bookId) {
 viewModel.processIntent(BookDetailViewModel.Intent.LoadBookDetail(bookId))
 }

 // Navigate to cart when added to cart
 LaunchedEffect(uiState.addedToCart) {
 if (uiState.addedToCart) {
 coroutineScope.launch {
 sheetState.hide()
 onDismiss()
 onNavigateToCart()
 }
 }
 }

 ModalBottomSheet(
 onDismissRequest = onDismiss,
 sheetState = sheetState
 ) {
 if (uiState.isLoading) {
 // Show loading state
 Box(modifier = Modifier.fillMaxWidth().height(200.dp), contentAlignment = Alignment.Center) {
 CircularProgressIndicator()
 }
 } else if (uiState.errorMessage != null) {
 // Show error state
 Box(modifier = Modifier.fillMaxWidth().padding(16.dp), contentAlignment = Alignment.Center) {
 Text(text = "Error: ${uiState.errorMessage}", color = MaterialTheme.colorScheme.error)
 }
 } else {
 // Show book details
 uiState.book?.let { book ->
 BookDetailSheetContent(
 book = book,
 onAddToCart = { bookId, amount ->
 viewModel.processIntent(BookDetailViewModel.Intent.AddToCart(bookId, amount))
 }
 )
 }
 }
 }
}
```

And update the necessary imports:

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/main/booksheet/BookDetailBottomSheet.kt
// Add these imports at the top of the file
import androidx.compose.foundation.layout.Box
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
```

These changes:

1. Created a BookDetailViewModel that extends MviViewModel with LoadBookDetail and AddToCart intents
2. Updated BookDetailBottomSheet to take a bookId instead of a Book object
3. Added state handling for loading, error, and success states
4. Uses LaunchedEffect to load book details when the sheet is shown
5. Watches for addedToCart state to navigate when an item is added to the cart
6. Handles displaying loading and error states

You'll need to adjust how the BookDetailBottomSheet is called in other parts of your app to pass the bookId and viewModel instead of the book object directly."}]}

