Looking at your Accordion component, I see a few opportunities for improvement. Here are the suggested changes:

```kotlin:app/src/main/java/tungp/android/bazarbooks/components/accordion/Accordion.kt
// ... existing imports ...

// Accordion state holder
class AccordionState(
 private val type: AccordionType,
 initialExpandedItems: List<String> = emptyList(),
 private val onValueChange: ((List<String>) -> Unit)? = null
) {
 // ... existing code ...
}

@Composable
fun rememberAccordionState(
 type: AccordionType = AccordionType.SINGLE,
 initialExpandedItems: List<String> = emptyList(),
 onValueChange: ((List<String>) -> Unit)? = null
): AccordionState {
 return remember {
 AccordionState(type, initialExpandedItems, onValueChange)
 }
}

@Composable
fun Accordion(
 modifier: Modifier = Modifier,
 type: AccordionType = AccordionType.SINGLE,
 defaultValue: String? = null,
 onValueChange: ((List<String>) -> Unit)? = null,
 state: AccordionState = rememberAccordionState(
 type, 
 initialExpandedItems = defaultValue?.let { listOf(it) } ?: emptyList(),
 onValueChange = onValueChange
 ),
 content: @Composable (AccordionState) -> Unit
) {
 // ... existing code ...
}

// ... existing AccordionItem implementation ...

@Composable
fun AccordionDemo() {
 BazarTheme {
 Column {
 // ... Single selection demo ...

 HorizontalDivider(Modifier.height(40.dp))

 // Multiple selection mode example
 Accordion(
 type = AccordionType.MULTIPLE,
 onValueChange = { expandedItems ->
 // Handle multiple expanded items
 Log.d("TAG", "AccordionDemo: expandedItems=$expandedItems")
 },
 defaultValue = "multi-2"
 ) { state ->
 // ... first two items ...

 AccordionItem(
 itemId = "multi-3",
 title = "Can I customize the appearance?", // Changed the duplicate title
 state = state
 ) {
 Text("Yes, you can customize colors, animations and other visual aspects by modifying the component.")
 }
 }
 }
 }
}
```

Key improvements:

1. Used the `let` function to simplify the initialization of `initialExpandedItems` in the Accordion function
2. Fixed the duplicate title in the multi-3 AccordionItem in the demo
3. Added different content for the third item in the demo to avoid duplication

These changes make the code more concise and fix the redundancy in the demo section where you had duplicate titles and content for the second and third accordion items."}]}

