@Composable
fun VendorDetailItem(
 vendor: Vendor,
 onClick: () -> Unit,
 modifier: Modifier = Modifier
) {
 Card(
 modifier = modifier
 .fillMaxWidth()
 .padding(vertical = 8.dp),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),
 onClick = onClick
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(16.dp),
 horizontalArrangement = Arrangement.spacedBy(16.dp)
 ) {
 // Vendor image
 Card(
 shape = MaterialTheme.shapes.small,
 colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
 ) {
 androidx.compose.foundation.Image(
 painter = rememberAsyncImagePainter(model = vendor.cover),
 contentDescription = vendor.title,
 modifier = Modifier.size(80.dp)
 )
 }

 Column(
 modifier = Modifier.weight(1f),
 verticalArrangement = Arrangement.spacedBy(4.dp)
 ) {
 Text(
 text = vendor.title,
 style = MaterialTheme.typography.titleMedium,
 fontWeight = FontWeight.Bold
 )
 Text(
 text = vendor.authorName,
 style = MaterialTheme.typography.bodyMedium
 )

 // Replace the star icons with our RatingComponent
 RatingComponent(
 rating = vendor.rating.toFloat(),
 starSize = 16.dp,
 starSpacing = 4.dp,
 modifier = Modifier.padding(vertical = 2.dp)
 )

 Text(
 text = "${vendor.booksCount} books",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.outline
 )
 }
 }
 }
}

// ... rest of the file remains the same ...
```

This implementation provides a flexible rating component with the following features:

1. Display-only or interactive modes
2. Customizable star size, color, and spacing
3. Support for partial/half stars
4. Easy integration into existing UI components
5. Preview composables for quick visual testing

You can now use this `RatingComponent` throughout your app wherever you need to display ratings or allow users to submit ratings. The component is highly customizable and can be styled to match your app's design system."}]}

